    /**
     * 프로젝트의 business_type 값을 템플릿 projectType key로 매핑.
     * 새 프로젝트 유형이 추가되면 이 함수에도 매핑 추가.
     */
    mapBusinessTypeToTemplateType(businessType) {
        const map = {
            '운영': 'operation',
            '운영사업': 'operation',
            '구축': 'construction',
            '구축사업': 'construction',
            'SW분리발주': 'sw-separate',
            'SW분리발주사업': 'sw-separate',
            'ISP': 'isp',
            'AI구축': 'ai',
            '클라우드': 'cloud',
            '유지관리': 'maintain',
            '컨설팅': 'consult',
            'PMO': 'pmo',
        };
        return map[businessType] || 'operation';
    }

